/**
 * GhostBrain Core — Autonomous Repair Engine
 *
 * Executes repair proposals generated by the task learning engine and
 * failure predictor. All actions are subject to PolicyGuard evaluation
 * before execution.
 *
 * SAFETY model:
 *   1. PolicyGuard.evaluate() is called for every repair proposal.
 *   2. DENY → log + alert, never execute.
 *   3. REQUIRE_HUMAN_APPROVAL → forward to signing relay (:7910).
 *   4. ALLOW + dryRun=false → execute the repair action.
 *
 * Repair strategies:
 *   restart_container    — docker stop/start or restart API call
 *   reallocate           — adjust CPU / memory quotas via hypervisor
 *   clear_cache          — prune unused Docker images + volumes
 *   redeploy_service     — pull latest image and recreate container
 *   config_fix           — write corrected config and restart
 *   scale_up             — spin up additional replica via hypervisor
 *   scale_down           — remove idle replica
 *
 * Circuit breaker: max REPAIR_MAX_PER_HOUR repairs per resource per hour.
 */

import { request }               from "undici";
import { observe_task }          from "./task_learning_engine.js";
import { store_decision }        from "./memory_engine.js";
import type { TaskProposal }     from "./task_learning_engine.js";
import { log }                   from "./observability/event_logger.js";

// ── Config ────────────────────────────────────────────────────────────────────

const SIGNING_RELAY      = process.env.SIGNING_RELAY_URL   ?? "http://localhost:7910";
const DOCKER_SOCKET      = process.env.DOCKER_SOCKET       ?? "unix:///var/run/docker.sock";
const DOCKER_HTTP        = process.env.DOCKER_HTTP         ?? "";
const DRY_RUN_GLOBAL     = process.env.REPAIR_DRY_RUN      === "1";
const REPAIR_MAX_PER_HOUR = Number(process.env.REPAIR_MAX_PER_HOUR ?? "4");

// ── Types ─────────────────────────────────────────────────────────────────────

export type RepairStrategy =
  | "restart_container" | "reallocate" | "clear_cache"
  | "redeploy_service"  | "config_fix" | "scale_up" | "scale_down";

export interface RepairRequest {
  resourceId:  string;
  layer:       "container" | "vm" | "service" | "chain";
  strategy:    RepairStrategy;
  params:      Record<string, unknown>;
  triggerEvent: string;
  rationale:   string;
  confidence:  number;
  dryRun?:     boolean;
}

export interface RepairResult {
  success:     boolean;
  strategy:    RepairStrategy;
  resourceId:  string;
  recoveryMs:  number;
  detail?:     string;
  dryRun:      boolean;
}

// ── Circuit breaker ───────────────────────────────────────────────────────────

const _repairHistory = new Map<string, number[]>();  // resourceId → timestamps

function circuitBreakerAllow(resourceId: string): boolean {
  const now  = Date.now();
  const hour = 60 * 60_000;
  const hist = (_repairHistory.get(resourceId) ?? []).filter(t => now - t < hour);
  _repairHistory.set(resourceId, hist);
  if (hist.length >= REPAIR_MAX_PER_HOUR) {
    log.warn("auto_repair: circuit_breaker", `too many repairs for ${resourceId} (${hist.length}/${REPAIR_MAX_PER_HOUR}/hr)`);
    return false;
  }
  hist.push(now);
  _repairHistory.set(resourceId, hist);
  return true;
}

// ── PolicyGuard stub ──────────────────────────────────────────────────────────
// Full implementation in core/policyEngine.ts — this check is a lightweight
// pre-flight so repair_engine can gate itself without a circular dependency.

type PolicyDecision = "ALLOW" | "DENY" | "REQUIRE_HUMAN_APPROVAL";

function evaluateRepairPolicy(req: RepairRequest): PolicyDecision {
  // Chain-layer repairs always require human approval
  if (req.layer === "chain") return "REQUIRE_HUMAN_APPROVAL";
  // Scale operations always require human approval
  if (req.strategy === "scale_up" || req.strategy === "scale_down") return "REQUIRE_HUMAN_APPROVAL";
  // Low-confidence proposals require human review
  if (req.confidence < 0.4) return "REQUIRE_HUMAN_APPROVAL";
  // Redeploy is reversible but risky — require human if confidence < 0.7
  if (req.strategy === "redeploy_service" && req.confidence < 0.7) return "REQUIRE_HUMAN_APPROVAL";
  return "ALLOW";
}

// ── Docker helpers ────────────────────────────────────────────────────────────

async function dockerPost(path: string): Promise<boolean> {
  try {
    const socketPath = DOCKER_HTTP ? undefined : DOCKER_SOCKET.replace(/^unix:\/\//, "");
    const origin     = DOCKER_HTTP || "http://localhost";
    const opts = {
      path,
      method: "POST" as const,
      headers: { Host: "docker", "Content-Length": "0" },
      bodyTimeout: 15_000,
      ...(socketPath ? { socketPath } : {}),
    };
    const res = await request(origin, opts);
    return res.statusCode < 300;
  } catch {
    return false;
  }
}

// ── Strategy implementations ──────────────────────────────────────────────────

async function restartContainer(resourceId: string): Promise<boolean> {
  // Find container by name first
  const ok = await dockerPost(`/containers/${encodeURIComponent(resourceId)}/restart`);
  return ok;
}

async function clearDockerCache(): Promise<boolean> {
  const ok = await dockerPost("/images/prune?filters={}");
  return ok;
}

async function forwardToSigningRelay(req: RepairRequest): Promise<void> {
  const proposal = {
    type:       "repair_proposal",
    resourceId: req.resourceId,
    strategy:   req.strategy,
    params:     req.params,
    rationale:  req.rationale,
    confidence: req.confidence,
    requires_human_review: true,
    submitted_at: new Date().toISOString(),
  };
  try {
    await request(SIGNING_RELAY + "/api/v1/proposals", {
      method:      "POST",
      headers:     { "content-type": "application/json" },
      body:        JSON.stringify(proposal),
      bodyTimeout: 5_000,
    });
    log.info("auto_repair: signing_relay", `forwarded ${req.resourceId}:${req.strategy}`);
  } catch (err) {
    log.warn("auto_repair: signing_relay_unreachable", "proposal logged only");
  }
}

// ── Main execute path ─────────────────────────────────────────────────────────

/**
 * Execute a repair request.  Returns the result (success/failure + metrics).
 */
export async function executeRepair(req: RepairRequest): Promise<RepairResult> {
  const startedAt = Date.now();
  const isDry     = DRY_RUN_GLOBAL || req.dryRun === true;

  // Policy gate
  const policy = evaluateRepairPolicy(req);
  const decisionPayload = {
    agent:          "GhostRepairBot",
    decisionType:   "repair",
    resourceId:     req.resourceId,
    layer:          req.layer as Parameters<typeof store_decision>[0]["layer"],
    rationale:      req.rationale,
    confidence:     req.confidence,
    actionTaken:    { strategy: req.strategy, params: req.params },
    requiresHuman:  policy === "REQUIRE_HUMAN_APPROVAL",
    policyGuard:    policy,
  };
  store_decision(decisionPayload);

  if (policy === "DENY") {
    log.warn("auto_repair: deny", `DENY for ${req.resourceId}:${req.strategy}`);
    return { success: false, strategy: req.strategy, resourceId: req.resourceId, recoveryMs: 0, detail: "PolicyGuard DENY", dryRun: isDry };
  }

  if (policy === "REQUIRE_HUMAN_APPROVAL") {
    await forwardToSigningRelay(req);
    return { success: false, strategy: req.strategy, resourceId: req.resourceId, recoveryMs: 0, detail: "Awaiting human approval at signing relay", dryRun: true };
  }

  // Circuit breaker
  if (!isDry && !circuitBreakerAllow(req.resourceId)) {
    return { success: false, strategy: req.strategy, resourceId: req.resourceId, recoveryMs: 0, detail: "Circuit breaker: too many repairs this hour", dryRun: isDry };
  }

  log.info("auto_repair: execute", `${req.resourceId}:${req.strategy} dry=${isDry}`);

  let success = false;
  let detail: string | undefined;

  if (!isDry) {
    try {
      switch (req.strategy) {
        case "restart_container":
          success = await restartContainer(req.resourceId); break;
        case "clear_cache":
          success = await clearDockerCache(); break;
        case "reallocate":
        case "config_fix":
        case "redeploy_service":
        case "scale_up":
        case "scale_down":
          // These require integration with the hypervisor / orchestration layer;
          // they are forwarded to the signing relay for now.
          await forwardToSigningRelay({ ...req, strategy: req.strategy });
          success = true;
          detail  = "Forwarded to signing relay for execution";
          break;
      }
    } catch (err) {
      detail  = String(err);
      success = false;
    }
  } else {
    success = true;  // dry-run always "succeeds"
    detail  = "DRY_RUN";
  }

  const recoveryMs = Date.now() - startedAt;

  // Record outcome in task learning engine
  observe_task({
    taskId:         `repair-${Date.now()}`,
    resourceId:     req.resourceId,
    layer:          req.layer,
    triggerEvent:   req.triggerEvent,
    actionTaken:    req.strategy,
    params:         req.params,
    startedAt,
    finishedAt:     Date.now(),
    success,
    errorDetail:    detail,
  });

  log.info("auto_repair: done", `${req.resourceId}:${req.strategy} success=${success} recoveryMs=${recoveryMs} dry=${isDry}`);
  return { success, strategy: req.strategy, resourceId: req.resourceId, recoveryMs, detail, dryRun: isDry };
}

/**
 * Convert a TaskProposal from task_learning_engine into a RepairRequest
 * and execute it.
 */
export async function executeProposal(
  proposal: TaskProposal,
  layer: RepairRequest["layer"] = "container",
  triggerEvent = "unknown",
): Promise<RepairResult> {
  return executeRepair({
    resourceId:  proposal.resourceId,
    layer,
    strategy:    proposal.action as RepairStrategy,
    params:      proposal.params,
    triggerEvent,
    rationale:   proposal.rationale,
    confidence:  proposal.confidence,
    dryRun:      proposal.dryRun,
  });
}

// ── Stats ─────────────────────────────────────────────────────────────────────

export function getRepairStats() {
  const now  = Date.now();
  const hour = 60 * 60_000;
  let recent = 0;
  for (const hist of _repairHistory.values()) {
    recent += hist.filter(t => now - t < hour).length;
  }
  return { repairsLastHour: recent, trackedResources: _repairHistory.size, maxPerHour: REPAIR_MAX_PER_HOUR };
}
